CREATE TABLE public.workspace_preferences (user_id uuid PRIMARY KEY, profiles jsonb NOT NULL DEFAULT '{}'::jsonb, saved_ids jsonb NOT NULL DEFAULT '[]'::jsonb, dismissed_ids jsonb NOT NULL DEFAULT '[]'::jsonb, updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT, INSERT, UPDATE, DELETE ON public.workspace_preferences TO authenticated; GRANT ALL ON public.workspace_preferences TO service_role; ALTER TABLE public.workspace_preferences ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users read their workspace" ON public.workspace_preferences FOR SELECT TO authenticated USING (auth.uid() = user_id); CREATE POLICY "Users create their workspace" ON public.workspace_preferences FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id); CREATE POLICY "Users update their workspace" ON public.workspace_preferences FOR UPDATE TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id); CREATE POLICY "Users remove their workspace" ON public.workspace_preferences FOR DELETE TO authenticated USING (auth.uid() = user_id);